insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-523', 'enf', null, 'Na infusão endovenosa contínua de amiodarona, o enfermeiro deve estar atento:', '["ao risco de flebite em acesso periférico, à hipotensão e à bradicardia, preferindo a diluição em soro glicosado 5%.","à necessidade de infusão em bolus rápido.","à diluição obrigatória em soro fisiológico em frasco de PVC, sem restrições.","à dispensa de monitorização cardíaca.","ao risco de hipoglicemia grave."]'::jsonb, 0, 'Para infusões prolongadas, prefere-se acesso venoso central.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-524', 'enf', null, 'Segundo as recomendações da ANVISA para prevenção de infecções, o equipo utilizado para a infusão de propofol deve ser trocado:', '["a cada 6 a 12 horas, conforme recomendação do fabricante, por se tratar de emulsão lipídica que favorece o crescimento microbiano.","a cada 7 dias.","apenas quando a bomba alarmar.","a cada 30 dias.","nunca, enquanto a infusão estiver contínua."]'::jsonb, 0, 'A manipulação deve ser feita com técnica asséptica rigorosa.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-525', 'enf', null, 'Sobre a administração endovenosa de cloreto de potássio, é correto afirmar:', '["deve ser sempre diluído e infundido em bomba de infusão, nunca em bolus, com monitorização conforme a concentração e a velocidade.","pode ser administrado em bolus rápido em situações de urgência.","dispensa diluição quando infundido em acesso central.","deve ser administrado por via intramuscular quando não há acesso.","não exige dupla checagem."]'::jsonb, 0, 'O KCl concentrado é medicamento de alta vigilância.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-526', 'enf', null, 'Foram prescritos 20 mEq de cloreto de potássio para diluição em soro. A ampola disponível é de KCl 19,1% (2,5 mEq/mL). O volume a ser aspirado é de:', '["8 mL.","2 mL.","20 mL.","10 mL.","5 mL."]'::jsonb, 0, '2,5 mEq — 1 mL; 20 mEq — x → x = 8 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-527', 'enf', null, 'Uma solução de heparina foi preparada com 25.000 UI em volume final de 250 mL. Para infundir 1.000 UI/h, a vazão da bomba deve ser de:', '["10 mL/h.","1 mL/h.","25 mL/h.","100 mL/h.","4 mL/h."]'::jsonb, 0, 'Concentração: 25.000 ÷ 250 = 100 UI/mL; 1.000 ÷ 100 = 10 mL/h.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-528', 'enf', null, 'Foram diluídas 100 UI de insulina regular em 100 mL de soro fisiológico. Para infundir 5 UI/h, a vazão deve ser de:', '["5 mL/h.","0,5 mL/h.","50 mL/h.","1 mL/h.","10 mL/h."]'::jsonb, 0, 'Concentração: 1 UI/mL; 5 UI/h = 5 mL/h. Monitora-se a glicemia capilar com frequência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-529', 'enf', null, 'Uma solução de noradrenalina com concentração de 16 mcg/mL está sendo infundida a 15 mL/h. A dose infundida, em mcg/min, é de:', '["4 mcg/min.","16 mcg/min.","240 mcg/min.","1 mcg/min.","8 mcg/min."]'::jsonb, 0, '16 × 15 = 240 mcg/h; 240 ÷ 60 = 4 mcg/min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-530', 'enf', null, 'Foram prescritos 250 mL de soro fisiológico para correr em 5 horas, em equipo microgotas. O gotejamento será de:', '["50 microgotas/min.","25 microgotas/min.","17 microgotas/min.","83 microgotas/min.","100 microgotas/min."]'::jsonb, 0, 'Microgotas/min = V ÷ T(h) = 250 ÷ 5 = 50.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-531', 'enf', null, 'Um paciente abre os olhos apenas ao estímulo doloroso, emite palavras inapropriadas e localiza a dor. Pela escala de coma de Glasgow, sua pontuação é:', '["10.","8.","12.","6.","14."]'::jsonb, 0, 'Abertura ocular à dor (pressão) = 2; palavras inapropriadas = 3; localiza = 5; total 10.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-532', 'enf', null, 'Na avaliação neurológica, a presença de anisocoria (pupilas de tamanhos diferentes) em paciente com traumatismo cranioencefálico e rebaixamento de consciência deve ser interpretada como:', '["sinal de alerta para possível herniação cerebral, exigindo comunicação imediata.","achado normal em todos os pacientes.","efeito esperado de colírio, sem necessidade de avaliação.","sinal de melhora neurológica.","indicação de alta hospitalar."]'::jsonb, 0, 'Alterações pupilares associadas à piora da consciência indicam gravidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-533', 'enf', null, 'No paciente com AVC, antes de iniciar a dieta por via oral, o enfermeiro deve:', '["realizar ou solicitar a triagem da deglutição, pelo risco de disfagia e broncoaspiração.","oferecer líquidos finos imediatamente.","dispensar a avaliação se o paciente estiver consciente.","manter o paciente em decúbito dorsal horizontal para alimentar.","oferecer a dieta apenas à noite."]'::jsonb, 0, 'A broncoaspiração é causa importante de pneumonia após o AVC.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-534', 'enf', null, 'No diagnóstico de enfermagem "Risco de quedas", segundo a NANDA-I, o enunciado é composto por:', '["título e fatores de risco, como idade avançada, uso de sedativos e alteração da mobilidade.","título, fatores relacionados e características definidoras.","apenas características definidoras.","nome da doença e prescrição médica.","título e resultado esperado."]'::jsonb, 0, 'Diagnósticos de risco não têm características definidoras, pois o problema ainda não ocorreu.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-535', 'enf', null, 'No diagnóstico de enfermagem "Padrão respiratório ineficaz", são exemplos de características definidoras:', '["dispneia, uso da musculatura acessória e alteração da frequência respiratória.","medo de cair.","perda de apetite isolada.","insônia.","prurido."]'::jsonb, 0, 'As características definidoras são os sinais e sintomas observados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-536', 'enf', null, 'Na priorização dos diagnósticos de enfermagem de um paciente, deve ser atendido primeiro:', '["\"Desobstrução ineficaz de vias aéreas\".","\"Ansiedade\".","\"Conhecimento deficiente\".","\"Insônia\".","\"Disposição para nutrição melhorada\"."]'::jsonb, 0, 'Problemas que ameaçam a vida (vias aéreas, respiração, circulação) têm prioridade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-537', 'enf', null, 'Segundo o Código de Ética dos Profissionais de Enfermagem, a captação e a divulgação de imagens de pacientes:', '["são vedadas sem autorização da pessoa ou de seu representante legal, respeitando a privacidade e a dignidade.","são permitidas para fins de divulgação em redes sociais, se o rosto não aparecer.","são permitidas sempre que o caso for raro.","dependem apenas da autorização da chefia.","são livres em ambientes públicos do hospital."]'::jsonb, 0, 'A exposição de pacientes viola a intimidade e a confidencialidade.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-538', 'enf', null, 'Segundo o Código de Ética dos Profissionais de Enfermagem, quando o local de trabalho não oferecer condições seguras para o exercício profissional, é direito do profissional:', '["suspender as atividades, individuais ou coletivas, exceto em situações de urgência e emergência, comunicando o fato ao COREN e à chefia.","abandonar os pacientes sem comunicação.","suspender inclusive os atendimentos de urgência e emergência.","delegar suas atividades a acompanhantes.","continuar trabalhando em silêncio, sem registrar."]'::jsonb, 0, 'A segurança do paciente deve ser preservada nas situações de urgência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-539', 'enf', null, 'O índice de Apgar de um recém-nascido com frequência cardíaca acima de 100 bpm, choro forte, boa flexão dos membros, careta à estimulação e cianose de extremidades é de:', '["8.","10.","6.","7.","9."]'::jsonb, 0, 'FC > 100 (2) + respiração/choro forte (2) + tônus em flexão (2) + careta (1) + cianose de extremidades (1) = 8.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-540', 'enf', null, 'No puerpério, a involução uterina normal caracteriza-se pela redução da altura do fundo uterino de aproximadamente:', '["1 cm por dia, tornando-se intrapélvico em cerca de 10 a 14 dias.","5 cm por dia.","10 cm na primeira hora.","1 cm por semana.","não há redução nas primeiras semanas."]'::jsonb, 0, 'Logo após o parto, o útero se encontra próximo à cicatriz umbilical.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-541', 'enf', null, 'No atendimento à criança politraumatizada, são diferenças anatômicas em relação ao adulto que influenciam o manejo da via aérea:', '["língua proporcionalmente maior, occipital proeminente e via aérea mais estreita e anteriorizada.","via aérea mais larga e menos flexível.","occipital menor que o do adulto.","língua proporcionalmente menor.","ausência de diferenças anatômicas relevantes."]'::jsonb, 0, 'Essas características aumentam o risco de obstrução e exigem posicionamento adequado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-542', 'enf', null, 'Na escala de sedação de Ramsay, o paciente cooperativo, orientado e tranquilo é classificado como:', '["Ramsay 2.","Ramsay 1.","Ramsay 4.","Ramsay 5.","Ramsay 6."]'::jsonb, 0, 'Ramsay 1: ansioso/agitado; 3: responde apenas a comandos; 6: sem resposta a estímulos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-543', 'enf', null, 'Na oxigenoterapia por cateter nasal, estima-se que cada 1 L/min acrescente cerca de 4% à fração inspirada de oxigênio. Assim, com 3 L/min, a FiO2 aproximada é de:', '["32%.","21%.","50%.","60%.","90%."]'::jsonb, 0, 'Ar ambiente: 21%; 1 L/min ≈ 24%; 2 L/min ≈ 28%; 3 L/min ≈ 32%.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-544', 'enf', null, 'São contraindicações à ventilação não invasiva (VNI):', '["rebaixamento do nível de consciência com incapacidade de proteger a via aérea, vômitos, instabilidade hemodinâmica grave e trauma de face.","edema agudo de pulmão cardiogênico.","exacerbação de DPOC com acidose respiratória leve.","paciente consciente e colaborativo.","desmame da ventilação invasiva em pacientes selecionados."]'::jsonb, 0, 'As três últimas são indicações clássicas da VNI.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-545', 'enf', null, 'O método considerado mais confiável para confirmar o posicionamento do tubo orotraqueal logo após a intubação é:', '["a capnografia em forma de onda.","a observação do embaçamento do tubo.","a pergunta ao paciente.","a medida da frequência cardíaca.","a ausculta isolada do epigástrio."]'::jsonb, 0, 'A ausculta e a radiografia de tórax complementam a avaliação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-546', 'enf', null, 'A cânula orofaríngea (Guedel) deve ser utilizada:', '["em pacientes inconscientes, sem reflexo de tosse ou vômito, com tamanho medido da comissura labial ao ângulo da mandíbula.","em todos os pacientes conscientes, para prevenir obstrução.","com tamanho medido do nariz ao queixo.","apenas em pacientes intubados.","como substituta da intubação em PCR prolongada."]'::jsonb, 0, 'Em pacientes com reflexo de vômito, pode provocar vômito e aspiração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-547', 'enf', null, 'A taxa de ocupação hospitalar de uma unidade é calculada pela razão entre:', '["o número de pacientes-dia e o número de leitos-dia no período, multiplicado por 100.","o número de altas e o número de leitos.","o número de óbitos e o número de internações.","o número de profissionais e o número de leitos.","o número de cirurgias e o número de salas."]'::jsonb, 0, 'Taxas muito altas sobrecarregam a equipe e aumentam riscos assistenciais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-548', 'enf', null, 'O tempo médio de permanência em uma unidade de internação é calculado pela razão entre:', '["o número de pacientes-dia e o número de saídas (altas, óbitos e transferências externas) no período.","o número de leitos e o número de profissionais.","o número de internações e o número de óbitos.","o número de pacientes-dia e o número de leitos.","o número de altas e o número de dias do mês."]'::jsonb, 0, 'É indicador de eficiência do uso dos leitos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-549', 'enf', null, 'Segundo a Lei Geral de Proteção de Dados Pessoais (Lei nº 13.709/2018), os dados referentes à saúde são classificados como:', '["dados pessoais sensíveis, que exigem proteção especial no tratamento.","dados públicos, de livre divulgação.","dados anônimos em qualquer situação.","dados financeiros.","dados sem qualquer proteção legal."]'::jsonb, 0, 'O acesso aos prontuários deve ser restrito aos profissionais envolvidos no cuidado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-550', 'enf', null, 'Segundo a Lei nº 13.787/2018, os prontuários de pacientes, digitalizados ou não, devem ser guardados por, no mínimo:', '["20 anos, a partir do último registro.","5 anos.","1 ano após a alta.","10 anos após o óbito, apenas.","não há prazo mínimo de guarda."]'::jsonb, 0, 'A lei regulamenta a digitalização e a guarda dos prontuários.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-551', 'enf', null, 'A Escala de Depressão Geriátrica (GDS-15) é utilizada na avaliação da pessoa idosa para:', '["rastrear sintomas depressivos.","avaliar a capacidade funcional para atividades básicas.","avaliar o risco de lesão por pressão.","medir a força muscular.","avaliar o estado nutricional."]'::jsonb, 0, 'Pontuações elevadas indicam a necessidade de avaliação mais detalhada.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-552', 'enf', null, 'Para os profissionais de saúde, são recomendadas, entre outras, as vacinas:', '["hepatite B, dupla adulto (dT/dTpa), tríplice viral e influenza, conforme a situação vacinal.","apenas BCG.","apenas febre amarela.","apenas rotavírus.","nenhuma, pois o uso de EPI dispensa a vacinação."]'::jsonb, 0, 'A vacinação protege o trabalhador e os pacientes; a varicela é indicada para suscetíveis.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-553', 'enf', null, 'Na precaução para aerossóis em ambiente hospitalar, o quarto ideal deve ter:', '["pressão negativa em relação às áreas adjacentes, com trocas de ar adequadas e filtragem do ar (HEPA) quando houver recirculação.","pressão positiva, para proteger o paciente.","porta aberta para facilitar a ventilação do corredor.","ar-condicionado comum compartilhado com outras enfermarias.","nenhuma exigência especial."]'::jsonb, 0, 'Na indisponibilidade, mantém-se quarto privativo, porta fechada e boa ventilação, conforme orientação da CCIH.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('enf-554', 'enf', null, 'Nos cuidados paliativos, a hipodermóclise é:', '["a infusão de líquidos e de alguns medicamentos por via subcutânea, alternativa útil quando a via oral não é possível e o acesso venoso é difícil.","a punção de veia profunda para infusão rápida.","a infusão de medicamentos por via intramuscular contínua.","a alimentação por sonda gástrica.","a administração de medicamentos por via retal."]'::jsonb, 0, 'É uma técnica segura, de baixo custo e pode ser usada no domicílio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
